import pandas as pd
import numpy as np
from collections import Counter

# Load data
df = pd.read_excel('/root/data.xlsx', sheet_name='Data', header=None, skiprows=9, usecols=[2,3,4,5,6,7,8,9])
df.columns = ['turn_number', 'game_number', 'r1', 'r2', 'r3', 'r4', 'r5', 'r6']
df = df.dropna(subset=['turn_number'])
df['turn_number'] = df['turn_number'].astype(int)
df['game_number'] = df['game_number'].astype(int)

# Define scoring functions
def score_high_and_often(rolls):
    c = Counter(rolls)
    max_val = max(rolls)
    return max_val * c[max_val]

def score_summation(rolls):
    return sum(rolls)

def score_highs_and_lows(rolls):
    hi = max(rolls)
    lo = min(rolls)
    return hi * lo * (hi - lo)

def score_only_two_numbers(rolls):
    if len(set(rolls)) == 2:
        return 30
    return 0

def score_all_the_numbers(rolls):
    if sorted(rolls) == [1, 2, 3, 4, 5, 6]:
        return 40
    return 0

def score_ordered(rolls):
    for i in range(len(rolls) - 3):
        subset = rolls[i:i+4]
        if all(subset[j+1] == subset[j] + 1 for j in range(3)):
            return 50
        if all(subset[j+1] == subset[j] - 1 for j in range(3)):
            return 50
    return 0

categories = ['high_and_often', 'summation', 'highs_and_lows', 'only_two', 'all_numbers', 'ordered']

score_funcs = {
    'high_and_often': score_high_and_often,
    'summation': score_summation,
    'highs_and_lows': score_highs_and_lows,
    'only_two': score_only_two_numbers,
    'all_numbers': score_all_the_numbers,
    'ordered': score_ordered,
}

# Compute scores for each turn
turn_scores = {}  # turn_number -> dict of category scores
turn_to_game = {}

for _, row in df.iterrows():
    rolls = [int(row['r1']), int(row['r2']), int(row['r3']), int(row['r4']), int(row['r5']), int(row['r6'])]
    turn = int(row['turn_number'])
    game = int(row['game_number'])

    scores = {c: score_funcs[c](rolls) for c in categories}
    turn_scores[turn] = scores
    turn_to_game[turn] = game

# For each game, find optimal category assignment to maximize combined score
def best_game_score_two_turns(t1_scores, t2_scores):
    best = 0
    for c1 in categories:
        for c2 in categories:
            if c1 != c2:
                total = t1_scores[c1] + t2_scores[c2]
                if total > best:
                    best = total
    return best

def best_game_score_one_turn(t_scores):
    return max(t_scores.values())

# Group turns by game
from collections import defaultdict
game_turns = defaultdict(list)
for turn_num, game_num in turn_to_game.items():
    game_turns[game_num].append(turn_num)

game_scores = {}
for game_num in sorted(game_turns.keys()):
    turns = sorted(game_turns[game_num])
    if len(turns) == 2:
        t1s = turn_scores[turns[0]]
        t2s = turn_scores[turns[1]]
        game_scores[game_num] = best_game_score_two_turns(t1s, t2s)
    elif len(turns) == 1:
        game_scores[game_num] = best_game_score_one_turn(turn_scores[turns[0]])
        print(f"Game {game_num} has only 1 turn (turn {turns[0]}), score = {game_scores[game_num]}")
    else:
        print(f"WARNING: Game {game_num} has {len(turns)} turns!")

print(f"Total games: {len(game_scores)}")

# Now: odd games -> Player 1, even games -> Player 2
# Match: game 1 vs game 2, game 3 vs game 4, ...
p1_wins = 0
p2_wins = 0
draws = 0

for i in range(1, 3001, 2):
    p1_game = i      # odd
    p2_game = i + 1   # even

    s1 = game_scores[p1_game]
    s2 = game_scores[p2_game]

    if s1 > s2:
        p1_wins += 1
    elif s2 > s1:
        p2_wins += 1
    else:
        draws += 1

print(f"\nPlayer 1 wins: {p1_wins}")
print(f"Player 2 wins: {p2_wins}")
print(f"Draws: {draws}")
answer = p1_wins - p2_wins
print(f"\nAnswer (P1 wins - P2 wins) = {answer}")

with open('/root/answer.txt', 'w') as f:
    f.write(str(answer))
print(f"Answer written to /root/answer.txt")

